package com.zidio.keystone.config;
import com.zidio.keystone.domain.*; import com.zidio.keystone.repository.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.time.*; import java.util.*;
@Component public class SlaScheduler { final WorkOrderRepository work; final NotificationRepository notifications; public SlaScheduler(WorkOrderRepository work,NotificationRepository notifications){this.work=work;this.notifications=notifications;} @Scheduled(fixedDelay=300000) public void check(){var jobs=work.findBySlaDueAtBeforeAndStatusNotIn(Instant.now(),List.of(WorkOrderStatus.CLOSED,WorkOrderStatus.CANCELLED));for(var x:jobs)if(x.getAssignee()!=null){var n=new Notification();n.setUser(x.getAssignee());n.setMessage("SLA breach: work order "+x.getCode()+" is overdue.");n.setCreatedAt(Instant.now());notifications.save(n);}}}
